use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

/// Secure session management system for multi-tenant SaaS platform
/// Implements role-based access control with hierarchical permissions

#[derive(Clone, Debug)]
pub struct Session {
    pub user_id: String,
    pub tenant_id: String,
    pub role_level: u32,  // 0=guest, 1=user, 2=manager, 3=admin, 4=superadmin
    pub issued_at: u64,
    pub expires_at: u64,
    pub permissions: Vec<String>,
}

#[derive(Clone, Debug)]
pub struct AccessPolicy {
    pub resource: String,
    pub min_role_level: u32,
    pub tenant_restricted: bool,
}

pub struct SessionStore {
    sessions: Arc<Mutex<HashMap<String, Session>>>,
    policies: Arc<Mutex<Vec<AccessPolicy>>>,
    revocation_list: Arc<Mutex<Vec<String>>>,
}

impl SessionStore {
    pub fn new() -> Self {
        let mut policies = Vec::new();
        policies.push(AccessPolicy {
            resource: "user_data".to_string(),
            min_role_level: 1,
            tenant_restricted: true,
        });
        policies.push(AccessPolicy {
            resource: "admin_panel".to_string(),
            min_role_level: 3,
            tenant_restricted: true,
        });
        policies.push(AccessPolicy {
            resource: "system_config".to_string(),
            min_role_level: 4,
            tenant_restricted: false,
        });
        policies.push(AccessPolicy {
            resource: "billing".to_string(),
            min_role_level: 2,
            tenant_restricted: true,
        });

        SessionStore {
            sessions: Arc::new(Mutex::new(HashMap::new())),
            policies: Arc::new(Mutex::new(policies)),
            revocation_list: Arc::new(Mutex::new(Vec::new())),
        }
    }

    /// Parse a session token from wire format
    /// Format: user_id|tenant_id|role_level|issued_at|expires_at|permissions
    pub fn parse_token(&self, token: &str) -> Option<Session> {
        let parts: Vec<&str> = token.split('|').collect();
        if parts.len() < 6 {
            return None;
        }

        let user_id = parts[0].to_string();
        let tenant_id = parts[1].to_string();

        // Parse role_level as unsigned - negative values will fail to parse
        let role_level: u32 = match parts[2].parse() {
            Ok(v) => v,
            Err(_) => return None,
        };

        // Validate role_level is within expected bounds
        if role_level > 4 {
            return None;
        }

        let issued_at: u64 = match parts[3].parse() {
            Ok(v) => v,
            Err(_) => return None,
        };

        let expires_at: u64 = match parts[4].parse() {
            Ok(v) => v,
            Err(_) => return None,
        };

        let permissions: Vec<String> = parts[5].split(',').map(|s| s.to_string()).collect();

        Some(Session {
            user_id,
            tenant_id,
            role_level,
            issued_at,
            expires_at,
            permissions,
        })
    }

    /// Register a session after token validation
    pub fn register_session(&self, token: &str) -> Result<String, String> {
        let session = self.parse_token(token).ok_or("Invalid token format")?;

        // Validate expiration
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        if session.expires_at < now {
            return Err("Token expired".to_string());
        }

        // Check revocation
        let revoked = self.revocation_list.lock().unwrap();
        if revoked.contains(&session.user_id) {
            return Err("Session revoked".to_string());
        }
        drop(revoked);

        let session_id = format!("sess_{}_{}", session.user_id, session.issued_at);
        let mut sessions = self.sessions.lock().unwrap();
        sessions.insert(session_id.clone(), session);

        Ok(session_id)
    }

    /// Core authorization check - determines if session can access resource
    /// Uses hierarchical role comparison with unsigned integers
    pub fn check_access(
        &self,
        session_id: &str,
        resource: &str,
        requesting_tenant: &str,
    ) -> Result<bool, String> {
        let sessions = self.sessions.lock().unwrap();
        let session = sessions.get(session_id)
            .ok_or("Session not found")?;

        // Verify session hasn't expired
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();

        if session.expires_at < now {
            return Err("Session expired".to_string());
        }

        let policies = self.policies.lock().unwrap();

        // Find matching policy
        let policy = policies.iter().find(|p| p.resource == resource);

        match policy {
            None => {
                // No policy means default deny
                Ok(false)
            }
            Some(policy) => {
                // Tenant isolation check
                if policy.tenant_restricted && session.tenant_id != requesting_tenant {
                    return Ok(false);
                }

                // Hierarchical role check with unsigned comparison
                // role_level is u32, so no signed comparison issues
                let authorized = session.role_level >= policy.min_role_level;

                Ok(authorized)
            }
        }
    }

    /// Elevate session privileges (admin action)
    pub fn elevate_session(&self, admin_session_id: &str, target_session_id: &str, new_level: u32) -> Result<(), String> {
        // Validate new_level is within bounds
        if new_level > 4 {
            return Err("Invalid role level".to_string());
        }

        // Hold the sessions lock continuously across the privilege check and the
        // mutation to avoid a TOCTOU race where the admin session could be
        // revoked/downgraded or sessions swapped between check and use.
        let mut sessions = self.sessions.lock().unwrap();

        {
            let admin = sessions.get(admin_session_id)
                .ok_or("Admin session not found")?;

            // Only superadmins can elevate
            if admin.role_level < 4 {
                return Err("Insufficient privileges".to_string());
            }
        }

        let target = sessions.get_mut(target_session_id)
            .ok_or("Target session not found")?;

        target.role_level = new_level;
        Ok(())
    }

    pub fn revoke_user(&self, user_id: &str) {
        let mut revoked = self.revocation_list.lock().unwrap();
        revoked.push(user_id.to_string());
    }

    /// Batch authorization check for multiple resources
    pub fn check_batch_access(
        &self,
        session_id: &str,
        resources: &[&str],
        requesting_tenant: &str,
    ) -> Result<HashMap<String, bool>, String> {
        let mut results = HashMap::new();
        for resource in resources {
            let access = self.check_access(session_id, resource, requesting_tenant)?;
            results.insert(resource.to_string(), access);
        }
        Ok(results)
    }
}

/// Audit log entry for compliance
#[derive(Debug)]
pub struct AuditEntry {
    pub timestamp: u64,
    pub session_id: String,
    pub resource: String,
    pub granted: bool,
}

pub struct AuditLog {
    entries: Arc<Mutex<Vec<AuditEntry>>>,
}

impl AuditLog {
    pub fn new() -> Self {
        AuditLog {
            entries: Arc::new(Mutex::new(Vec::new())),
        }
    }

    pub fn record(&self, session_id: &str, resource: &str, granted: bool) {
        let entry = AuditEntry {
            timestamp: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_secs(),
            session_id: session_id.to_string(),
            resource: resource.to_string(),
            granted,
        };
        let mut entries = self.entries.lock().unwrap();
        entries.push(entry);
    }

    pub fn get_entries_for_session(&self, session_id: &str) -> Vec<String> {
        let entries = self.entries.lock().unwrap();
        entries.iter()
            .filter(|e| e.session_id == session_id)
            .map(|e| format!("{}: {} -> {}", e.timestamp, e.resource, e.granted))
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_access_control() {
        let store = SessionStore::new();

        // Create a normal user session
        let token = "user1|tenant_a|1|1000000000|9999999999|read,write";
        let session_id = store.register_session(token).unwrap();

        // User can access user_data in their tenant
        assert_eq!(store.check_access(&session_id, "user_data", "tenant_a").unwrap(), true);
        // User cannot access admin_panel
        assert_eq!(store.check_access(&session_id, "admin_panel", "tenant_a").unwrap(), false);
    }

    #[test]
    fn test_admin_access() {
        let store = SessionStore::new();

        let token = "admin1|tenant_a|3|1000000000|9999999999|all";
        let session_id = store.register_session(token).unwrap();

        assert_eq!(store.check_access(&session_id, "admin_panel", "tenant_a").unwrap(), true);
        assert_eq!(store.check_access(&session_id, "system_config", "tenant_a").unwrap(), false);
    }

    #[test]
    fn test_tenant_isolation() {
        let store = SessionStore::new();

        let token = "user2|tenant_b|3|1000000000|9999999999|all";
        let session_id = store.register_session(token).unwrap();

        // Admin in tenant_b cannot access tenant_a resources
        assert_eq!(store.check_access(&session_id, "admin_panel", "tenant_a").unwrap(), false);
    }

    #[test]
    fn test_role_hierarchy() {
        let store = SessionStore::new();

        // Test that higher roles can access lower-level resources
        let token = "super1|tenant_a|4|1000000000|9999999999|all";
        let session_id = store.register_session(token).unwrap();

        assert_eq!(store.check_access(&session_id, "system_config", "tenant_a").unwrap(), true);
        assert_eq!(store.check_access(&session_id, "admin_panel", "tenant_a").unwrap(), true);
        assert_eq!(store.check_access(&session_id, "user_data", "tenant_a").unwrap(), true);
    }

    #[test]
    fn test_negative_role_rejected() {
        let store = SessionStore::new();

        // Negative role values should fail to parse as u32
        let token = "evil|tenant_a|-1|1000000000|9999999999|all";
        assert!(store.register_session(token).is_err());
    }

    #[test]
    fn test_excessive_role_rejected() {
        let store = SessionStore::new();

        // Role > 4 should be rejected
        let token = "evil|tenant_a|5|1000000000|9999999999|all";
        assert!(store.register_session(token).is_err());
    }
}
